public class CqlService
{
    private static final Logger logger = LoggerFactory.getLogger(CqlService.class);

    public ResultSet executeCql(File dbUnixSocketFile, String query) throws ConnectionClosedException
    {
        CqlSession session = UnixSocketCQLAccess.get(dbUnixSocketFile).orElse(null);

        if (session == null || session.isClosed())
        {
            throw new ConnectionClosedException("Internal connection to Cassandra closed");
        }

        try
        {
            return session.execute(query);
        }
        catch (NoNodeAvailableException e)
        {
            try
            {
                session.close();
            }
            catch (Throwable t)
            {
                // close quietly
            }

            throw e;
        }
    }

    public ResultSet executePreparedStatement(File cassandraUnixSocketFile, String query,  Object... values) throws ConnectionClosedException
    {
        CqlSession session = UnixSocketCQLAccess.get(cassandraUnixSocketFile).orElse(null);

        if (session == null || session.isClosed())
        {
            throw new ConnectionClosedException("Internal connection to Cassandra closed");
        }

        SimpleStatementBuilder ssb = new SimpleStatementBuilder(query);

        for (Object obj : values)
        {
            ssb = ssb.addPositionalValue(obj);
        }

        try
        {
            return session.execute(ssb.build());
        }
        catch (NoNodeAvailableException e)
        {
            try
            {
                session.close();
            }
            catch (Throwable t)
            {
                // close quietly
            }

            throw e;
        }
    }
}

@ApplicationPath("/")
public class ManagementApplication extends Application
{
    private static final Logger logger = LoggerFactory.getLogger(ManagementApplication.class);

    public final File dbUnixSocketFile;
    public final File dbHome;
    public final File dbExe;
    public final Collection<String> dbExtraJvmArgs;
    public final CqlService cqlService;


    private final LifecycleResources lifecycle;
    private final Set<Object> resources;
    private final AtomicReference<STATE> requestedState = new AtomicReference<>(STATE.UNKNOWN);
    private final AtomicReference<String> activeProfile = new AtomicReference<>(null);

    public ManagementApplication(File dbHome, File dbExe, File dbUnixSocketFile, CqlService cqlService, Collection<String> dbExtraJvmArgs)
    {
        this.dbUnixSocketFile = dbUnixSocketFile;
        this.dbHome = dbHome;
        this.dbExe = dbExe;
        this.dbExtraJvmArgs = dbExtraJvmArgs;
        this.lifecycle = new LifecycleResources(this);
        this.cqlService = cqlService;

        resources = ImmutableSet.of(
                lifecycle,
                new K8OperatorResources(this),
                new KeyspaceOpsResources(this),
                new com.datastax.mgmtapi.resources.v1.KeyspaceOpsResources(this),
                new MetadataResources(this),
                new NodeOpsResources(this),
                new com.datastax.mgmtapi.resources.v1.NodeOpsResources(this),
                new TableOpsResources(this),
                new com.datastax.mgmtapi.resources.v1.TableOpsResources(this),
                new AuthResources(this),
                new OpenApiResource(),
                new SwaggerSerializers()
        );
    }

    @Override
    public Set<Object> getSingletons()
    {
        return resources;
    }

    public boolean checkState()
    {
        try
        {
            STATE currentState = getRequestedState();
            logger.debug("Current Requested State is {}", currentState);
            if (currentState != STATE.STOPPED)
            {
                Response r = lifecycle.startNode(getActiveProfile(), null);
                return r.getStatus() >= 200 && r.getStatus() < 300;
            }

            return true;
        }
        catch (Throwable t)
        {
            logger.error("Error checking state", t);
            return false;
        }
    }

    public STATE getRequestedState()
    {
        return requestedState.get();
    }

    public void setRequestedState(STATE state)
    {
        requestedState.set(state);
    }

    public String getActiveProfile()
    {
        return activeProfile.get();
    }

    public void setActiveProfile(String profile)
    {
        activeProfile.set(profile);
    }

    public enum STATE {
        UNKNOWN,
        STARTED,
        STOPPED
    }
}

public class NettyJaxrsIPCServer extends NettyJaxrsServer
{
    private final AtomicReference<IPCController> activeServerRef = new AtomicReference<>();

    private final EventLoopGroup eventLoopGroup;
    private final File socketFile;
    private Map<ChannelOption, Object> channelOptions = Collections.emptyMap();
    private List<ChannelHandler> httpChannelHandlers = Collections.emptyList();

    private final int maxRequestSize = 1024 * 1024 * 10;
    private final int maxInitialLineLength = 4096;
    private final int maxHeaderSize = 8192;
    private final int maxChunkSize = 8192;
    private final int idleTimeout = 60;
    // From the internals of Resteasy
    private final EmbeddedServerHelper serverHelper = new EmbeddedServerHelper();

    public NettyJaxrsIPCServer(EventLoopGroup eventLoopGroup, File socketFile)
    {
        this.eventLoopGroup = eventLoopGroup;
        this.socketFile = socketFile;
    }

    @Override
    public NettyJaxrsServer setChannelOptions(final Map<ChannelOption, Object> channelOptions) {
        this.channelOptions = channelOptions == null ? Collections.<ChannelOption, Object>emptyMap() : channelOptions;
        return this;
    }

    @Override
    public NettyJaxrsServer setHttpChannelHandlers(final List<ChannelHandler> httpChannelHandlers) {
        this.httpChannelHandlers = httpChannelHandlers == null ? Collections.<ChannelHandler>emptyList() : httpChannelHandlers;
        return this;
    }

    @Override
    public NettyJaxrsServer start()
    {
        synchronized (activeServerRef)
        {
            IPCController activeServer = activeServerRef.get();
            if (activeServer != null && activeServer.isActive())
                return this;

            if (activeServer != null)
            {
                activeServer.start();
            }
            else
            {
                serverHelper.checkDeployment(deployment);

                // dynamically set the root path (the user can rewrite it by calling setRootResourcePath)
                String appPath = serverHelper.checkAppDeployment(deployment);
                if (appPath != null && (root == null || "".equals(root))) {
                  setRootResourcePath(appPath);
                }

                activeServer = IPCController.newServer()
                        .withEventLoop(eventLoopGroup)
                        .withSocketFile(socketFile)
                        .withChannelOptions(channelOptions)
                        .withChannelHandler(new ChannelInitializer<Channel>() {
                            @Override
                            protected void initChannel(Channel ch) throws Exception
                            {
                                setupHandlers(ch, createRequestDispatcher(), RestEasyHttpRequestDecoder.Protocol.HTTP);
                            }
                        }).build();

                activeServer.start();
                boolean b = activeServerRef.compareAndSet(null, activeServer);
                assert b : "Already active";
            }
        }
        return this;
    }

    @Override
    public void stop()
    {
         synchronized (activeServerRef)
         {
             IPCController activeServer = activeServerRef.get();
             if (activeServer != null)
                 activeServer.stop();
         }
    }

    protected void setupHandlers(Channel ch, RequestDispatcher dispatcher, RestEasyHttpRequestDecoder.Protocol protocol) {
        ChannelPipeline channelPipeline = ch.pipeline();

        channelPipeline.addLast(new HttpRequestDecoder(maxInitialLineLength, maxHeaderSize, maxChunkSize));
        channelPipeline.addLast(new HttpResponseEncoder());
        channelPipeline.addLast(new HttpObjectAggregator(maxRequestSize));
        channelPipeline.addLast(httpChannelHandlers.toArray(new ChannelHandler[httpChannelHandlers.size()]));
        channelPipeline.addLast(new RestEasyHttpRequestDecoder(dispatcher.getDispatcher(), root, protocol));
        channelPipeline.addLast(new RestEasyHttpResponseEncoder());

        if (idleTimeout > 0)
        {
            channelPipeline.addLast("idleStateHandler", new IdleStateHandler(0, 0, idleTimeout));
        }

        channelPipeline.addLast(new RequestHandler(dispatcher));
    }

}

public class NettyJaxrsTLSServer extends NettyJaxrsServer
{
    private final SslContext sslContext;
    private final EventLoopGroup eventLoopGroup = new NioEventLoopGroup(2);
    private final Map<ChannelOption, Object> channelOptions = Collections.emptyMap();
    private final int maxRequestSize = 1024 * 1024 * 10;
    private final int maxInitialLineLength = 4096;
    private final int maxHeaderSize = 8192;
    private final int maxChunkSize = 8192;
    private final int idleTimeout = 60;
    // From the internals of Resteasy
    private final EmbeddedServerHelper serverHelper = new EmbeddedServerHelper();

    public NettyJaxrsTLSServer(SslContext sslContext)
    {
        this.sslContext = sslContext;
    }

    @Override
    public NettyJaxrsServer start() {
        serverHelper.checkDeployment(deployment);
        // dynamically set the root path (the user can rewrite it by calling setRootResourcePath)
        String appPath = serverHelper.checkAppDeployment(deployment);
        if (appPath != null && (root == null || "".equals(root))) {
            setRootResourcePath(appPath);
        }

        // Configure the server.
        bootstrap.group(eventLoopGroup)
                .channel(NioServerSocketChannel.class)
                .childHandler(new ChannelInitializer<Channel>()
                {
                    @Override
                    protected void initChannel(Channel ch) throws Exception
                    {
                        setupHandlers(ch, createRequestDispatcher(), RestEasyHttpRequestDecoder.Protocol.HTTPS);
                    }
                })
                .option(ChannelOption.SO_BACKLOG, 100)
                .childOption(ChannelOption.SO_KEEPALIVE, true);

        for (Map.Entry<ChannelOption, Object> entry : channelOptions.entrySet()) {
            bootstrap.option(entry.getKey(), entry.getValue());
        }

        final InetSocketAddress socketAddress;
        if (null == hostname || hostname.isEmpty()) {
            socketAddress = new InetSocketAddress(configuredPort);
        } else {
            socketAddress = new InetSocketAddress(hostname, configuredPort);
        }

        Channel channel = bootstrap.bind(socketAddress).syncUninterruptibly().channel();
        runtimePort = ((InetSocketAddress) channel.localAddress()).getPort();
        return this;
    }

    protected void setupHandlers(Channel ch, RequestDispatcher dispatcher, RestEasyHttpRequestDecoder.Protocol protocol) {
        ChannelPipeline channelPipeline = ch.pipeline();

        channelPipeline.addFirst(sslContext.newHandler(ch.alloc()));

        channelPipeline.addLast(new HttpRequestDecoder(maxInitialLineLength, maxHeaderSize, maxChunkSize));
        channelPipeline.addLast(new HttpResponseEncoder());
        channelPipeline.addLast(new HttpObjectAggregator(maxRequestSize));
        channelPipeline.addLast(new RestEasyHttpRequestDecoder(dispatcher.getDispatcher(), root, protocol));
        channelPipeline.addLast(new RestEasyHttpResponseEncoder());

        if (idleTimeout > 0)
        {
            channelPipeline.addLast("idleStateHandler", new IdleStateHandler(0, 0, idleTimeout));
        }

        channelPipeline.addLast(new RequestHandler(dispatcher));
    }


    @Override
    public void stop()
    {
        runtimePort = -1;
        eventLoopGroup.shutdownGracefully();
    }
}

public class UnixCmds
{
    private static final Logger logger = LoggerFactory.getLogger(UnixCmds.class);

    public static Optional<File> which(String exeStr) throws IOException
    {
        return ShellUtils.executeShellWithHandlers(
                String.format("/bin/which %s", exeStr),
                (input, err) -> {
                    File exe = new File(input.readLine().toLowerCase());
                    if (exe.canExecute())
                        return Optional.of(exe);

                    return Optional.empty();
                },
                (exitCode, err) -> Optional.empty()
        );
    }

    public static Optional<Integer> findDbProcessWithMatchingArg(String filterStr) throws IOException
    {
        return ShellUtils.executeShellWithHandlers(
                "/bin/ps -eo pid,command= | grep Dcassandra.server_process",
                (input, err) -> {

                    Integer pid = null;
                    String line;
                    while ( (line = input.readLine()) != null)
                    {
                        if (line.contains(filterStr))
                        {
                            if (pid != null)
                                throw new RuntimeException("Found more than 1 pid for: " + filterStr);

                            logger.debug("Match found on {}", line);
                            pid = Integer.valueOf(line.trim().split("\\s")[0]);
                        }
                    }

                    return Optional.ofNullable(pid);
                },
                (exitCode, err) -> Optional.empty()
        );
    }

}

public class ShellUtils
{
    private static final Logger logger = LoggerFactory.getLogger(ShellUtils.class);


    // This is from http://stackoverflow.com/a/20725050/322152.  We're not using org.apache.commons
    // .exec.CommandLine
    // because it fails to parse "run 'echo "foo"'" correctly (v1.3 misses off the final ')
    public static String[] split(CharSequence string)
    {
        List<String> tokens = new ArrayList<>();
        boolean escaping = false;
        char quoteChar = ' ';
        boolean quoting = false;
        StringBuilder current = new StringBuilder();
        for (int i = 0; i < string.length(); i++)
        {
            char c = string.charAt(i);
            if (escaping)
            {
                current.append(c);
                escaping = false;
            }
            else if (c == '\\' && !(quoting && quoteChar == '\''))
            {
                escaping = true;
            }
            else if (quoting && c == quoteChar)
            {
                quoting = false;
            }
            else if (!quoting && (c == '\'' || c == '"'))
            {
                quoting = true;
                quoteChar = c;
            }
            else if (!quoting && Character.isWhitespace(c))
            {
                if (current.length() > 0)
                {
                    tokens.add(current.toString());
                    current = new StringBuilder();
                }
            }
            else
            {
                current.append(c);
            }
        }
        if (current.length() > 0)
        {
            tokens.add(current.toString());
        }
        return tokens.toArray(new String[]{});
    }

    public static String escape(String param)
    {
        return escape(
                param,
                false
        );
    }

    public static String escape(
            String param,
            boolean forceQuote
    )
    {
        String escapedQuotesParam =  param.replaceAll("'", "'\"'\"'");

        return forceQuote || escapedQuotesParam.contains(" ") ?
               "'" + escapedQuotesParam + "'" :
               escapedQuotesParam;
    }

    public static List<String> wrapCommandWithBash(
            String command,
            boolean remoteCommand
    )
    {
        List<String> fullCmd = new ArrayList<>();
        fullCmd.add("/bin/bash");
        fullCmd.add("-o");
        fullCmd.add("pipefail"); // pipe returns first non-zero exit code
        if (remoteCommand)
        {
            // Remote commands should be run in a login shell, since they'll need the environment
            // to be set up correctly.  Local commands should already be in this situation,
            // since fallout should have been run with the correct environment already in place.
            fullCmd.add("-l");
        }
        fullCmd.add("-c"); // execute following command
        if (remoteCommand)
        {
            // Remote commands need to be quoted again, to prevent expansion as they're passed to ssh.
            String escapedCmd = ShellUtils.escape(
                    command,
                    true
            );
            fullCmd.add(escapedCmd);
        }
        else
        {
            fullCmd.add(command);
        }
        return fullCmd;
    }

    public static Process executeShell(
            String command,
            Map<String, String> environment
    )
    {
        List<String> cmds = wrapCommandWithBash(
                command,
                false
        );
        logger.trace(
                "Executing locally: {}, Env {}",
                String.join(
                        " ",
                        cmds
                ),
                environment
        );
        ProcessBuilder pb = new ProcessBuilder(cmds);
        pb.environment().putAll(environment);
        try
        {
            return pb.start();
        }
        catch (IOException e)
        {
            throw new RuntimeException(e);
        }
    }

    public interface ThrowingBiFunction<ArgType, Arg2Type, ResType>
    {
        ResType apply(
                ArgType t,
                Arg2Type t2
        ) throws IOException;
    }


    public static <T> T executeShellWithHandlers(
            String command,
            ThrowingBiFunction<BufferedReader, BufferedReader, T> handler,
            ThrowingBiFunction<Integer, BufferedReader, T> errorHandler
    )
            throws IOException
    {
        return executeShellWithHandlers(
                command,
                handler,
                errorHandler,
                Collections.emptyMap()
        );
    }

    public static <T> T executeShellWithHandlers(
            String command,
            ThrowingBiFunction<BufferedReader, BufferedReader, T> handler,
            ThrowingBiFunction<Integer, BufferedReader, T> errorHandler,
            Map<String, String> environment
    )
            throws IOException
    {
        Process ps = ShellUtils.executeShell(
                command,
                environment
        );

        // We need to read _everything_ from stdin + stderr as buffering will interfere with large amounts of
        // data. If we don't read everything here, the process might just get blocked, because of a buffer
        // being full.
        ByteArrayOutputStream stdinBuffer = new ByteArrayOutputStream();
        ByteArrayOutputStream stderrBuffer = new ByteArrayOutputStream();
        int ec;
        try (InputStream stdin = ps.getInputStream(); InputStream stderr = ps.getErrorStream())
        {
            byte[] buf = new byte[1024];
            while (true)
            {
                int avStdin;
                int avStderr;
                int rd;

                avStdin = Math.min(stdin.available(), buf.length);
                if (avStdin > 0)
                {
                    rd = stdin.read(buf, 0, avStdin);
                    if (rd > 0)
                        stdinBuffer.write(buf, 0, rd);
                }
                avStderr = Math.min(stderr.available(), buf.length);
                if (avStderr > 0)
                {
                    rd = stderr.read(buf, 0, avStderr);
                    if (rd > 0)
                        stderrBuffer.write(buf, 0, rd);
                }

                if (avStdin == 0 && avStderr == 0)
                {
                    try
                    {
                        ec = ps.exitValue();
                        break;
                    }
                    catch (IllegalThreadStateException ignore)
                    {
                        try
                        {
                            Thread.sleep(50L);
                        }
                        catch (InterruptedException e)
                        {
                            //ignore
                        }
                    }
                }
            }
        }

        try (BufferedReader input = new BufferedReader(new StringReader(stdinBuffer.toString("UTF-8")));
             BufferedReader error = new BufferedReader(new StringReader(stderrBuffer.toString("UTF-8"))))
        {
            if (ec != 0)
            {
                return errorHandler.apply(
                        ps.exitValue(),
                        error
                );
            }

            return handler.apply(
                    input,
                    error
            );
        }
    }
}

public class UnixSocketCQLAccess
{
    private static final Logger logger = LoggerFactory.getLogger(UnixSocketCQLAccess.class);
    private static final ConcurrentMap<File, UnixSocketCQLAccess> cache = Maps.newConcurrentMap();
    private final CqlSession session;
    private final EndPoint unixSocketEndpoint;

    public static Optional<CqlSession> get(File unixSocket)
    {
        if (!unixSocket.exists()) {
            logger.info("Cannot create Driver CQLSession as the driver socket has not been created. This should resolve once Cassandra has started and created the socket at {}", unixSocket.getAbsolutePath());
            return Optional.empty();
        }
        while (true)
        {
            UnixSocketCQLAccess client = cache.get(unixSocket);

            if (client != null && !client.session.isClosed())
                return Optional.of(client.session);

            //might throw exceptions if unix sock does not exist, so we might have nothing to return
            try
            {
                UnixSocketCQLAccess newClient = new UnixSocketCQLAccess(unixSocket);
                if (client == null && cache.putIfAbsent(unixSocket, newClient) == null)
                    return Optional.of(newClient.session);

                if (client != null && cache.replace(unixSocket, client, newClient))
                    return Optional.of(newClient.session);

                //Someone else opened a session, so close and try again
                newClient.session.close();
            }
            catch (AllNodesFailedException e)
            {
                return Optional.empty();
            }
        }
    }

    private UnixSocketCQLAccess(File unixSocket)
    {
        unixSocketEndpoint = new EndPoint()
        {
            @Override
            public SocketAddress resolve()
            {
                return new DomainSocketAddress(unixSocket);
            }

            @Override
            public String asMetricPrefix()
            {
                return unixSocket.toString();
            }

            @Override
            public String toString()
            {
                return unixSocket.toString();
            }
        };

        session = new LocalSessionBuilder(unixSocketEndpoint)
                .withConfigLoader(DriverConfigLoader.programmaticBuilder()
                        .withDuration(DefaultDriverOption.REQUEST_TIMEOUT, Duration.of(30, SECONDS))
                        // force protocol V4 for now
                        .withString(DefaultDriverOption.PROTOCOL_VERSION, "V4")
                        .build())
                .build();
    }

    static class LocalSessionBuilder extends CqlSessionBuilder
    {
        final EndPoint unixSocketEndpoint;

        LocalSessionBuilder(EndPoint unixSocketEndpoint)
        {
            super();
            this.unixSocketEndpoint = unixSocketEndpoint;
            this.addContactEndPoint(unixSocketEndpoint);
        }

        @Override
        protected DriverContext buildContext(DriverConfigLoader configLoader, List<TypeCodec<?>> typeCodecs,
                NodeStateListener nodeStateListener, SchemaChangeListener schemaChangeListener, RequestTracker requestTracker,
                Map<String, String> localDatacenters, Map<String, Predicate<Node>> nodeFilters, ClassLoader classLoader)
        {
            return new LocalDriverContext(unixSocketEndpoint, configLoader, typeCodecs, nodeStateListener, schemaChangeListener,
                    requestTracker, localDatacenters, nodeFilters, classLoader);
        }
    }

    static class LocalDriverContext extends DefaultDriverContext
    {
        final EndPoint unixSocketEndpoint;
        volatile Node unixSocketNode = null;

        LocalDriverContext(EndPoint unixSocketEndpoint, DriverConfigLoader configLoader, List<TypeCodec<?>> typeCodecs,
                NodeStateListener nodeStateListener, SchemaChangeListener schemaChangeListener, RequestTracker requestTracker,
                Map<String, String> localDatacenters, Map<String, Predicate<Node>> nodeFilters, ClassLoader classLoader)
        {
            super(configLoader, typeCodecs, nodeStateListener, schemaChangeListener, requestTracker, localDatacenters, nodeFilters,
                    classLoader);

            this.unixSocketEndpoint = unixSocketEndpoint;
        }

        @Override
        protected TopologyMonitor buildTopologyMonitor()
        {
            return new DefaultTopologyMonitor(this)
            {
                // This local node can have multiple endpoints (unix-sock, tcp-ip) for the same UUID
                // The driver can't handle this so we filter the tcp-ip one out.
                // Note only the local unix-socket connection can see these dups
                @Override
                public CompletionStage<Iterable<NodeInfo>> refreshNodeList()
                {
                    return super.refreshNodeList()
                            .thenApply(nodeInfos -> {
                                Map<UUID, NodeInfo> filteredNodeInfo = new LinkedHashMap<>();
                                for (NodeInfo nodeInfo : nodeInfos)
                                {
                                    NodeInfo dupNode = filteredNodeInfo.get(nodeInfo.getHostId());

                                    if (dupNode != null)
                                    {
                                        //Keep the unix socket one, otherwise overwrite the tcp-ip one.
                                        if (dupNode.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                                            continue;

                                        // This means there's an actual dup UUID!
                                        if (!nodeInfo.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                                            throw new IllegalArgumentException(String.format("Multiple entries with same key: %s and %s", dupNode, nodeInfo));
                                    }

                                    filteredNodeInfo.put(nodeInfo.getHostId(), nodeInfo);
                                }

                                return filteredNodeInfo.values();
                            });
                }
            };
        }

        @Override
        protected NettyOptions buildNettyOptions()
        {
            final EventLoopGroup eventLoopGroup = eventLoop();

            return new DefaultNettyOptions(this) {

                @Override
                public Class<? extends Channel> channelClass()
                {
                    return Epoll.isAvailable() ? EpollDomainSocketChannel.class : KQueueDomainSocketChannel.class;
                }

                @Override
                public EventLoopGroup ioEventLoopGroup()
                {
                    return eventLoopGroup;
                }

                @Override
                public EventExecutorGroup adminEventExecutorGroup()
                {
                    return eventLoopGroup;
                }


                @Override
                public Future<Void> onClose() {
                    DefaultPromise<Void> closeFuture = new DefaultPromise<>(GlobalEventExecutor.INSTANCE);
                    GlobalEventExecutor.INSTANCE.execute(
                            () -> {
                                DriverExecutionProfile config = getConfig().getDefaultProfile();
                                PromiseCombiner combiner = new PromiseCombiner();
                                combiner.add(
                                        adminEventExecutorGroup().shutdownGracefully(
                                                config.getInt(DefaultDriverOption.NETTY_IO_SHUTDOWN_QUIET_PERIOD),
                                                config.getInt(DefaultDriverOption.NETTY_IO_SHUTDOWN_TIMEOUT),
                                                TimeUnit.valueOf(config.getString(DefaultDriverOption.NETTY_IO_SHUTDOWN_UNIT))));

                                combiner.finish(closeFuture);
                            });
                    closeFuture.addListener(f -> getTimer().stop());
                    return closeFuture;
                }
            };
        }

        @Override
        protected ReconnectionPolicy buildReconnectionPolicy()
        {
            ReconnectionPolicy.ReconnectionSchedule noBackoff = () -> Duration.ofSeconds(10);

            return new ReconnectionPolicy() {
                @Override
                public ReconnectionSchedule newNodeSchedule(Node node)
                {
                    return noBackoff;
                }

                @Override
                public ReconnectionSchedule newControlConnectionSchedule(boolean isInitialConnection)
                {
                    return noBackoff;
                }

                @Override
                public void close()
                {

                }
            };
        }

        @Override
        protected Map<String, LoadBalancingPolicy> buildLoadBalancingPolicies()
        {
            return Collections.singletonMap(DriverExecutionProfile.DEFAULT_NAME, new LoadBalancingPolicy() {

                DistanceReporter distanceReporter;

                @Override
                public void init(Map<UUID, Node> nodes, DistanceReporter distanceReporter)
                {
                    this.distanceReporter = distanceReporter;

                    for (Map.Entry<UUID, Node> e : nodes.entrySet())
                    {
                        Node n = e.getValue();
                        if (n.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                        {
                            unixSocketNode = n;
                            distanceReporter.setDistance(n, NodeDistance.LOCAL);
                        }
                    }
                }

                @Override
                public Queue<Node> newQueryPlan(Request request, Session session)
                {
                    final Node uxNode = unixSocketNode;
                    return uxNode == null ? QueryPlan.EMPTY : new SimpleQueryPlan(uxNode);
                }

                /**
                 * The key for all these is to always pass the defaultNode instance in since the
                 * query plan will always return this.
                 */
                @Override
                public void onAdd(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = node;
                        distanceReporter.setDistance(node, NodeDistance.LOCAL);
                    }
                }

                @Override
                public void onUp(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = node;
                        distanceReporter.setDistance(node, NodeDistance.LOCAL);
                    }
                }

                @Override
                public void onDown(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = null;
                        distanceReporter.setDistance(node, NodeDistance.IGNORED);
                    }
                }

                @Override
                public void onRemove(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = null;
                        distanceReporter.setDistance(node, NodeDistance.IGNORED);
                    }
                }

                @Override
                public void close()
                {

                }
            });
        }

        @Override
        protected RequestProcessorRegistry buildRequestProcessorRegistry() {
            String logPrefix = getSessionName();

            // regular requests (sync and async)
            CqlRequestAsyncProcessor cqlRequestAsyncProcessor = new CqlRequestAsyncProcessor();
            CqlRequestSyncProcessor cqlRequestSyncProcessor =
                    new CqlRequestSyncProcessor(cqlRequestAsyncProcessor);

            // prepare requests (sync and async)
            CqlPrepareAsyncProcessor cqlPrepareAsyncProcessor = new CqlPrepareAsyncProcessor();
            CqlPrepareSyncProcessor cqlPrepareSyncProcessor =
                    new CqlPrepareSyncProcessor(cqlPrepareAsyncProcessor);


            return new RequestProcessorRegistry(
                    logPrefix,
                    cqlRequestSyncProcessor,
                    cqlRequestAsyncProcessor,
                    cqlPrepareSyncProcessor,
                    cqlPrepareAsyncProcessor);
        }
    }

    private static EventLoopGroup eventLoop()
    {
        if (Epoll.isAvailable())
        {
            Epoll.ensureAvailability();
            return new EpollEventLoopGroup(2);
        }

        if (KQueue.isAvailable())
        {
            KQueue.ensureAvailability();
            return new KQueueEventLoopGroup(2);
        }

        throw new RuntimeException();
    }
}

@Path("/api/v0/ops/auth")
public class AuthResources
{
    private final ManagementApplication app;
    private final CqlService cqlService;

    public AuthResources(ManagementApplication application)
    {
        this.app = application;
        this.cqlService = application.cqlService;
    }

    @POST
    @Path("/role/")
    @Operation(summary = "Creates a new user role", operationId = "createRole")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Role created",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "OK"
            )
        )
    )
    @ApiResponse(responseCode = "400", description = "Username and/or password is empty",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "Username is empty"
            )
        )
    )
    public Response createRole(
            @QueryParam(value = "username")String name,
            @QueryParam(value = "is_superuser") Boolean isSuperUser,
            @QueryParam(value = "can_login") Boolean canLogin,
            @QueryParam(value = "password") String password),
            HttpServletRequest request
    {
        return handle(() -> {

            if (StringUtils.isBlank(name))
