public class CqlService
{
    private static final Logger logger = LoggerFactory.getLogger(CqlService.class);

    public ResultSet executeCql(File dbUnixSocketFile, String query) throws ConnectionClosedException
    {
        CqlSession session = UnixSocketCQLAccess.get(dbUnixSocketFile).orElse(null);

        if (session == null || session.isClosed())
        {
            throw new ConnectionClosedException("Internal connection to Cassandra closed");
        }

        try
        {
            return session.execute(query);
        }
        catch (NoNodeAvailableException e)
        {
            try
            {
                session.close();
            }
            catch (Throwable t)
            {
                // close quietly
            }

            throw e;
        }
    }

    public ResultSet executePreparedStatement(File cassandraUnixSocketFile, String query,  Object... values) throws ConnectionClosedException
    {
        CqlSession session = UnixSocketCQLAccess.get(cassandraUnixSocketFile).orElse(null);

        if (session == null || session.isClosed())
        {
            throw new ConnectionClosedException("Internal connection to Cassandra closed");
        }

        SimpleStatementBuilder ssb = new SimpleStatementBuilder(query);

        for (Object obj : values)
        {
            ssb = ssb.addPositionalValue(obj);
        }

        try
        {
            return session.execute(ssb.build());
        }
        catch (NoNodeAvailableException e)
        {
            try
            {
                session.close();
            }
            catch (Throwable t)
            {
                // close quietly
            }

            throw e;
        }
    }
}

@ApplicationPath("/")
public class ManagementApplication extends Application
{
    private static final Logger logger = LoggerFactory.getLogger(ManagementApplication.class);

    public final File dbUnixSocketFile;
    public final File dbHome;
    public final File dbExe;
    public final Collection<String> dbExtraJvmArgs;
    public final CqlService cqlService;


    private final LifecycleResources lifecycle;
    private final Set<Object> resources;
    private final AtomicReference<STATE> requestedState = new AtomicReference<>(STATE.UNKNOWN);
    private final AtomicReference<String> activeProfile = new AtomicReference<>(null);

    public ManagementApplication(File dbHome, File dbExe, File dbUnixSocketFile, CqlService cqlService, Collection<String> dbExtraJvmArgs)
    {
        this.dbUnixSocketFile = dbUnixSocketFile;
        this.dbHome = dbHome;
        this.dbExe = dbExe;
        this.dbExtraJvmArgs = dbExtraJvmArgs;
        this.lifecycle = new LifecycleResources(this);
        this.cqlService = cqlService;

        resources = ImmutableSet.of(
                lifecycle,
                new K8OperatorResources(this),
                new KeyspaceOpsResources(this),
                new com.datastax.mgmtapi.resources.v1.KeyspaceOpsResources(this),
                new MetadataResources(this),
                new NodeOpsResources(this),
                new com.datastax.mgmtapi.resources.v1.NodeOpsResources(this),
                new TableOpsResources(this),
                new com.datastax.mgmtapi.resources.v1.TableOpsResources(this),
                new AuthResources(this),
                new OpenApiResource(),
                new SwaggerSerializers()
        );
    }

    @Override
    public Set<Object> getSingletons()
    {
        return resources;
    }

    public boolean checkState()
    {
        try
        {
            STATE currentState = getRequestedState();
            logger.debug("Current Requested State is {}", currentState);
            if (currentState != STATE.STOPPED)
            {
                Response r = lifecycle.startNode(getActiveProfile(), null);
                return r.getStatus() >= 200 && r.getStatus() < 300;
            }

            return true;
        }
        catch (Throwable t)
        {
            logger.error("Error checking state", t);
            return false;
        }
    }

    public STATE getRequestedState()
    {
        return requestedState.get();
    }

    public void setRequestedState(STATE state)
    {
        requestedState.set(state);
    }

    public String getActiveProfile()
    {
        return activeProfile.get();
    }

    public void setActiveProfile(String profile)
    {
        activeProfile.set(profile);
    }

    public enum STATE {
        UNKNOWN,
        STARTED,
        STOPPED
    }
}

public class ResponseTools {

    public static String getSingleRowStringResponse(final File dbUnixSocketFile, CqlService cqlService, String query, Object... params) throws ConnectionClosedException {
        Row row = getRow(dbUnixSocketFile, cqlService, query, params);
        String queryResponse = null;
        if (row != null)
        {
            queryResponse = row.getString(0);
        }

        return queryResponse;
    }

    public static Object getSingleRowResponse(final File dbUnixSocketFile, CqlService cqlService, String query, Object... params) throws ConnectionClosedException {
        Row row = getRow(dbUnixSocketFile, cqlService, query, params);
        Object queryResponse = null;
        if (row != null)
        {
            queryResponse = row.getObject(0);
        }

        return queryResponse;
    }

    private static Row getRow(File dbUnixSocketFile, CqlService cqlService, String query, Object[] params) throws ConnectionClosedException {
        ResultSet rs;

        if(params.length > 0) {
            rs = cqlService.executePreparedStatement(dbUnixSocketFile, query, params);
        } else {
            rs = cqlService.executeCql(dbUnixSocketFile, query);
        }

        Row row = rs.one();
        return row;
    }

}

public class RepairRequest
{

    @JsonProperty(value = "keyspace_name", required = true)
    public final String keyspaceName;

    @JsonProperty(value = "tables", required = false)
    public final List<String> tables;

    @JsonProperty(value = "full", required = false)
    public final Boolean full;

    @JsonCreator
    public RepairRequest(@JsonProperty("keyspace_name") String keyspaceName, @JsonProperty("tables") List<String> tables, @JsonProperty(value = "full") Boolean full)
    {
        this.keyspaceName = keyspaceName;
        this.tables = tables;
        this.full = full == null ? Boolean.FALSE : full;
    }

  @Override
  public int hashCode() {
    int hash = 7;
    hash = 89 * hash + Objects.hashCode(this.keyspaceName);
    hash = 89 * hash + Objects.hashCode(this.tables);
    hash = 89 * hash + Objects.hashCode(this.full);
    return hash;
  }

  @Override
  public boolean equals(Object obj) {
    if (this == obj)
    {
        return true;
    }
    if (obj == null)
    {
        return false;
    }
    if (getClass() != obj.getClass())
    {
        return false;
    }

    final RepairRequest other = (RepairRequest) obj;
    if (!Objects.equals(this.keyspaceName, other.keyspaceName))
    {
        return false;
    }
    if (!Objects.equals(this.tables, other.tables))
    {
        return false;
    }
    if (!Objects.equals(this.full, other.full))
    {
        return false;
    }
    return true;
  }
}

public class TakeSnapshotRequest implements Serializable {

    @JsonProperty(value = "snapshot_name", required = false)
    public final String snapshotName;

    @JsonProperty(value = "keyspaces", required = false)
    public final List<String> keyspaces;

    @JsonProperty(value = "table_name", required = false)
    public final String tableName;

    @JsonProperty(value = "skip_flush", required = false)
    public final Boolean skipFlush;

    @JsonProperty(value = "keyspace_tables", required = false)
    public final List<String> keyspaceTables;

    @JsonCreator
    public TakeSnapshotRequest(
            @JsonProperty("snapshot_name") String snapshotName,
            @JsonProperty("keyspaces") List<String> keyspaces,
            @JsonProperty("table_name") String tableName,
            @JsonProperty(value = "skip_flush") Boolean skipFlush,
            @JsonProperty("keyspace_tables") List<String> keyspaceTables)
    {
        this.snapshotName = snapshotName == null ? Long.toString(System.currentTimeMillis()) : snapshotName;;
        this.keyspaces = keyspaces;
        this.tableName = tableName;
        this.skipFlush = skipFlush == null ? Boolean.FALSE : skipFlush;
        this.keyspaceTables = keyspaceTables;
    }

    @Override
    public int hashCode() {
        int hash = 5;
        hash = 83 * hash + Objects.hashCode(this.snapshotName);
        hash = 83 * hash + Objects.hashCode(this.keyspaces);
        hash = 83 * hash + Objects.hashCode(this.tableName);
        hash = 83 * hash + Objects.hashCode(this.skipFlush);
        hash = 83 * hash + Objects.hashCode(this.keyspaceTables);
        return hash;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
        {
            return true;
        }
        if (obj == null)
        {
            return false;
        }
        if (getClass() != obj.getClass())
        {
            return false;
        }
        final TakeSnapshotRequest other = (TakeSnapshotRequest) obj;
        if (!Objects.equals(this.snapshotName, other.snapshotName))
        {
            return false;
        }
        if (!Objects.equals(this.keyspaces, other.keyspaces))
        {
            return false;
        }
        if (!Objects.equals(this.tableName, other.tableName))
        {
            return false;
        }
        if (!Objects.equals(this.skipFlush, other.skipFlush))
        {
            return false;
        }
        if (!Objects.equals(this.keyspaceTables, other.keyspaceTables))
        {
            return false;
        }
        return true;
    }

}

public class UnixSocketCQLAccess
{
    private static final Logger logger = LoggerFactory.getLogger(UnixSocketCQLAccess.class);
    private static final ConcurrentMap<File, UnixSocketCQLAccess> cache = Maps.newConcurrentMap();
    private final CqlSession session;
    private final EndPoint unixSocketEndpoint;

    public static Optional<CqlSession> get(File unixSocket)
    {
        if (!unixSocket.exists()) {
            logger.info("Cannot create Driver CQLSession as the driver socket has not been created. This should resolve once Cassandra has started and created the socket at {}", unixSocket.getAbsolutePath());
            return Optional.empty();
        }
        while (true)
        {
            UnixSocketCQLAccess client = cache.get(unixSocket);

            if (client != null && !client.session.isClosed())
                return Optional.of(client.session);

            //might throw exceptions if unix sock does not exist, so we might have nothing to return
            try
            {
                UnixSocketCQLAccess newClient = new UnixSocketCQLAccess(unixSocket);
                if (client == null && cache.putIfAbsent(unixSocket, newClient) == null)
                    return Optional.of(newClient.session);

                if (client != null && cache.replace(unixSocket, client, newClient))
                    return Optional.of(newClient.session);

                //Someone else opened a session, so close and try again
                newClient.session.close();
            }
            catch (AllNodesFailedException e)
            {
                return Optional.empty();
            }
        }
    }

    private UnixSocketCQLAccess(File unixSocket)
    {
        unixSocketEndpoint = new EndPoint()
        {
            @Override
            public SocketAddress resolve()
            {
                return new DomainSocketAddress(unixSocket);
            }

            @Override
            public String asMetricPrefix()
            {
                return unixSocket.toString();
            }

            @Override
            public String toString()
            {
                return unixSocket.toString();
            }
        };

        session = new LocalSessionBuilder(unixSocketEndpoint)
                .withConfigLoader(DriverConfigLoader.programmaticBuilder()
                        .withDuration(DefaultDriverOption.REQUEST_TIMEOUT, Duration.of(30, SECONDS))
                        // force protocol V4 for now
                        .withString(DefaultDriverOption.PROTOCOL_VERSION, "V4")
                        .build())
                .build();
    }

    static class LocalSessionBuilder extends CqlSessionBuilder
    {
        final EndPoint unixSocketEndpoint;

        LocalSessionBuilder(EndPoint unixSocketEndpoint)
        {
            super();
            this.unixSocketEndpoint = unixSocketEndpoint;
            this.addContactEndPoint(unixSocketEndpoint);
        }

        @Override
        protected DriverContext buildContext(DriverConfigLoader configLoader, List<TypeCodec<?>> typeCodecs,
                NodeStateListener nodeStateListener, SchemaChangeListener schemaChangeListener, RequestTracker requestTracker,
                Map<String, String> localDatacenters, Map<String, Predicate<Node>> nodeFilters, ClassLoader classLoader)
        {
            return new LocalDriverContext(unixSocketEndpoint, configLoader, typeCodecs, nodeStateListener, schemaChangeListener,
                    requestTracker, localDatacenters, nodeFilters, classLoader);
        }
    }

    static class LocalDriverContext extends DefaultDriverContext
    {
        final EndPoint unixSocketEndpoint;
        volatile Node unixSocketNode = null;

        LocalDriverContext(EndPoint unixSocketEndpoint, DriverConfigLoader configLoader, List<TypeCodec<?>> typeCodecs,
                NodeStateListener nodeStateListener, SchemaChangeListener schemaChangeListener, RequestTracker requestTracker,
                Map<String, String> localDatacenters, Map<String, Predicate<Node>> nodeFilters, ClassLoader classLoader)
        {
            super(configLoader, typeCodecs, nodeStateListener, schemaChangeListener, requestTracker, localDatacenters, nodeFilters,
                    classLoader);

            this.unixSocketEndpoint = unixSocketEndpoint;
        }

        @Override
        protected TopologyMonitor buildTopologyMonitor()
        {
            return new DefaultTopologyMonitor(this)
            {
                // This local node can have multiple endpoints (unix-sock, tcp-ip) for the same UUID
                // The driver can't handle this so we filter the tcp-ip one out.
                // Note only the local unix-socket connection can see these dups
                @Override
                public CompletionStage<Iterable<NodeInfo>> refreshNodeList()
                {
                    return super.refreshNodeList()
                            .thenApply(nodeInfos -> {
                                Map<UUID, NodeInfo> filteredNodeInfo = new LinkedHashMap<>();
                                for (NodeInfo nodeInfo : nodeInfos)
                                {
                                    NodeInfo dupNode = filteredNodeInfo.get(nodeInfo.getHostId());

                                    if (dupNode != null)
                                    {
                                        //Keep the unix socket one, otherwise overwrite the tcp-ip one.
                                        if (dupNode.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                                            continue;

                                        // This means there's an actual dup UUID!
                                        if (!nodeInfo.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                                            throw new IllegalArgumentException(String.format("Multiple entries with same key: %s and %s", dupNode, nodeInfo));
                                    }

                                    filteredNodeInfo.put(nodeInfo.getHostId(), nodeInfo);
                                }

                                return filteredNodeInfo.values();
                            });
                }
            };
        }

        @Override
        protected NettyOptions buildNettyOptions()
        {
            final EventLoopGroup eventLoopGroup = eventLoop();

            return new DefaultNettyOptions(this) {

                @Override
                public Class<? extends Channel> channelClass()
                {
                    return Epoll.isAvailable() ? EpollDomainSocketChannel.class : KQueueDomainSocketChannel.class;
                }

                @Override
                public EventLoopGroup ioEventLoopGroup()
                {
                    return eventLoopGroup;
                }

                @Override
                public EventExecutorGroup adminEventExecutorGroup()
                {
                    return eventLoopGroup;
                }


                @Override
                public Future<Void> onClose() {
                    DefaultPromise<Void> closeFuture = new DefaultPromise<>(GlobalEventExecutor.INSTANCE);
                    GlobalEventExecutor.INSTANCE.execute(
                            () -> {
                                DriverExecutionProfile config = getConfig().getDefaultProfile();
                                PromiseCombiner combiner = new PromiseCombiner();
                                combiner.add(
                                        adminEventExecutorGroup().shutdownGracefully(
                                                config.getInt(DefaultDriverOption.NETTY_IO_SHUTDOWN_QUIET_PERIOD),
                                                config.getInt(DefaultDriverOption.NETTY_IO_SHUTDOWN_TIMEOUT),
                                                TimeUnit.valueOf(config.getString(DefaultDriverOption.NETTY_IO_SHUTDOWN_UNIT))));

                                combiner.finish(closeFuture);
                            });
                    closeFuture.addListener(f -> getTimer().stop());
                    return closeFuture;
                }
            };
        }

        @Override
        protected ReconnectionPolicy buildReconnectionPolicy()
        {
            ReconnectionPolicy.ReconnectionSchedule noBackoff = () -> Duration.ofSeconds(10);

            return new ReconnectionPolicy() {
                @Override
                public ReconnectionSchedule newNodeSchedule(Node node)
                {
                    return noBackoff;
                }

                @Override
                public ReconnectionSchedule newControlConnectionSchedule(boolean isInitialConnection)
                {
                    return noBackoff;
                }

                @Override
                public void close()
                {

                }
            };
        }

        @Override
        protected Map<String, LoadBalancingPolicy> buildLoadBalancingPolicies()
        {
            return Collections.singletonMap(DriverExecutionProfile.DEFAULT_NAME, new LoadBalancingPolicy() {

                DistanceReporter distanceReporter;

                @Override
                public void init(Map<UUID, Node> nodes, DistanceReporter distanceReporter)
                {
                    this.distanceReporter = distanceReporter;

                    for (Map.Entry<UUID, Node> e : nodes.entrySet())
                    {
                        Node n = e.getValue();
                        if (n.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                        {
                            unixSocketNode = n;
                            distanceReporter.setDistance(n, NodeDistance.LOCAL);
                        }
                    }
                }

                @Override
                public Queue<Node> newQueryPlan(Request request, Session session)
                {
                    final Node uxNode = unixSocketNode;
                    return uxNode == null ? QueryPlan.EMPTY : new SimpleQueryPlan(uxNode);
                }

                /**
                 * The key for all these is to always pass the defaultNode instance in since the
                 * query plan will always return this.
                 */
                @Override
                public void onAdd(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = node;
                        distanceReporter.setDistance(node, NodeDistance.LOCAL);
                    }
                }

                @Override
                public void onUp(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = node;
                        distanceReporter.setDistance(node, NodeDistance.LOCAL);
                    }
                }

                @Override
                public void onDown(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = null;
                        distanceReporter.setDistance(node, NodeDistance.IGNORED);
                    }
                }

                @Override
                public void onRemove(Node node)
                {
                    if (node.getEndPoint().resolve().equals(unixSocketEndpoint.resolve()))
                    {
                        unixSocketNode = null;
                        distanceReporter.setDistance(node, NodeDistance.IGNORED);
                    }
                }

                @Override
                public void close()
                {

                }
            });
        }

        @Override
        protected RequestProcessorRegistry buildRequestProcessorRegistry() {
            String logPrefix = getSessionName();

            // regular requests (sync and async)
            CqlRequestAsyncProcessor cqlRequestAsyncProcessor = new CqlRequestAsyncProcessor();
            CqlRequestSyncProcessor cqlRequestSyncProcessor =
                    new CqlRequestSyncProcessor(cqlRequestAsyncProcessor);

            // prepare requests (sync and async)
            CqlPrepareAsyncProcessor cqlPrepareAsyncProcessor = new CqlPrepareAsyncProcessor();
            CqlPrepareSyncProcessor cqlPrepareSyncProcessor =
                    new CqlPrepareSyncProcessor(cqlPrepareAsyncProcessor);


            return new RequestProcessorRegistry(
                    logPrefix,
                    cqlRequestSyncProcessor,
                    cqlRequestAsyncProcessor,
                    cqlPrepareSyncProcessor,
                    cqlPrepareAsyncProcessor);
        }
    }

    private static EventLoopGroup eventLoop()
    {
        if (Epoll.isAvailable())
        {
            Epoll.ensureAvailability();
            return new EpollEventLoopGroup(2);
        }

        if (KQueue.isAvailable())
        {
            KQueue.ensureAvailability();
            return new KQueueEventLoopGroup(2);
        }

        throw new RuntimeException();
    }
}

@Path("/api/v0/ops/keyspace")
public class KeyspaceOpsResources
{
    private static final Logger logger = LoggerFactory.getLogger(KeyspaceOpsResources.class);
    private static final ObjectMapper jsonMapper = new ObjectMapper();

    private final ManagementApplication app;
    private final CqlService cqlService;

    public KeyspaceOpsResources(ManagementApplication application) {
        this.app = application;
        this.cqlService = application.cqlService;
    }

    @POST
    @Path("/cleanup")
    @Consumes(MediaType.APPLICATION_JSON)
    @Operation(summary = "Triggers the immediate cleanup of keys no longer belonging to a node. By default, clean all keyspaces. This operation is blocking and will return the executed job after finishing.",
            operationId = "cleanup")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Job ID for keyspace cleanup process",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(
                implementation = String.class
            ),
            examples = @ExampleObject(
                value = "d69d1d95-9348-4460-95d2-ae342870fade"
            )
        )
    )
    public Response cleanup(KeyspaceRequest keyspaceRequest)
    {
        return NodeOpsResources.handle(() ->
        {
            List<String> tables = keyspaceRequest.tables;
            if (CollectionUtils.isEmpty(tables)) {
                tables = new ArrayList<>();
            }

            String keyspaceName = keyspaceRequest.keyspaceName;
            if (StringUtils.isBlank(keyspaceName))
            {
                keyspaceName = "NON_LOCAL_STRATEGY";
            }

            if (StringUtils.equalsAnyIgnoreCase(keyspaceName, "system", "system_schema"))
            {
                return Response.ok("OK").build();
            }

            return Response.ok(ResponseTools.getSingleRowStringResponse(app.dbUnixSocketFile, cqlService, "CALL NodeOps.forceKeyspaceCleanup(?, ?, ?, ?)",
                    keyspaceRequest.jobs, keyspaceName, tables, false)).build();
        });
    }

    @POST
    @Path("/refresh")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "SSTables loaded successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "OK"
            )
        )
    )
    @ApiResponse(responseCode = "400", description = "Keyspace name or Table name not provided",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "Must provide a keyspace name"
            )
        )
    )
    @Operation(summary = "Load newly placed SSTables to the system without restart", operationId = "refresh")
    public Response refresh(@QueryParam(value="keyspaceName")String keyspaceName, @QueryParam(value="table")String table)
    {
        return NodeOpsResources.handle(() ->
        {
            if (StringUtils.isBlank(keyspaceName))
            {
                return Response.status(HttpStatus.SC_BAD_REQUEST).entity("Must provide a keyspace name").build();
            }

            if (StringUtils.isBlank(table))
            {
                return Response.status(HttpStatus.SC_BAD_REQUEST).entity("table must be provided").build();
            }

            cqlService.executePreparedStatement(app.dbUnixSocketFile, "CALL NodeOps.loadNewSSTables(?, ?)", keyspaceName, table);

            return Response.ok("OK").build();
        });
    }

    @POST
    @Path("/create")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Keyspace created successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "OK"
            )
        )
    )
    @ApiResponse(responseCode = "400", description = "Keyspace name or Replication Settings not provided",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "Keyspace creation failed. Non-empty 'keyspace_name' must be provided"
            )
        )
    )
    @Consumes(MediaType.APPLICATION_JSON)
    @Operation(summary = "Create a new keyspace with the given name and replication settings", operationId = "createKeyspace")
    public Response create(CreateOrAlterKeyspaceRequest createOrAlterKeyspaceRequest)
    {
        return NodeOpsResources.handle(() ->
        {
            if (StringUtils.isBlank(createOrAlterKeyspaceRequest.keyspaceName))
            {
                return Response.status(HttpStatus.SC_BAD_REQUEST).entity("Keyspace creation failed. Non-empty 'keyspace_name' must be provided").build();
            }

            if (null == createOrAlterKeyspaceRequest.replicationSettings || createOrAlterKeyspaceRequest.replicationSettings.isEmpty())
            {
                return Response.status(HttpStatus.SC_BAD_REQUEST).entity("Keyspace creation failed. 'replication_settings' must be provided").build();
            }

            cqlService.executePreparedStatement(app.dbUnixSocketFile, "CALL NodeOps.createKeyspace(?, ?)",
                    createOrAlterKeyspaceRequest.keyspaceName, createOrAlterKeyspaceRequest.replicationSettingsAsMap());

            return Response.ok("OK").build();
        });
    }

    @POST
    @Path("/alter")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Keyspace Replication Settings altered successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "OK"
            )
        )
    )
    @ApiResponse(responseCode = "400", description = "Keyspace name or Replication Settings not provided",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "Altering Keyspace failed. Non-empty 'keyspace_name' must be provided"
            )
        )
    )
    @Consumes(MediaType.APPLICATION_JSON)
    @Operation(summary = "Alter the replication settings of an existing keyspace", operationId = "alterKeyspace")
    public Response alter(CreateOrAlterKeyspaceRequest createOrAlterKeyspaceRequest)
    {
        return NodeOpsResources.handle(() ->
        {
            if (StringUtils.isBlank(createOrAlterKeyspaceRequest.keyspaceName))
            {
                return Response.status(HttpStatus.SC_BAD_REQUEST).entity("Altering Keyspace failed. Non-empty 'keyspace_name' must be provided").build();
            }

            if (null == createOrAlterKeyspaceRequest.replicationSettings || createOrAlterKeyspaceRequest.replicationSettings.isEmpty())
            {
                return Response.status(HttpStatus.SC_BAD_REQUEST).entity("Altering Keyspace failed. 'replication_settings' must be provided").build();
            }

            cqlService.executePreparedStatement(app.dbUnixSocketFile, "CALL NodeOps.alterKeyspace(?, ?)",
                    createOrAlterKeyspaceRequest.keyspaceName, createOrAlterKeyspaceRequest.replicationSettingsAsMap());

            return Response.ok("OK").build();
        });
    }

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    @ApiResponse(responseCode = "200", description = "List of Keyspaces",
        content = @Content(
            mediaType = MediaType.APPLICATION_JSON,
            examples = @ExampleObject(
                value = "[\n    \"system_schema\",\n    \"system\",\n    \"system_auth\",\n    \"system_distributed\",\n    \"system_traces\"\n]"
            )
        )
    )
    @Consumes(MediaType.APPLICATION_JSON)
    @Operation(summary = "List the keyspaces existing in the cluster", operationId = "listKeyspaces")
    public Response list(@QueryParam(value="keyspaceName")String keyspaceName)
    {
        return NodeOpsResources.handle(() ->
        {
            ResultSet result = cqlService.executePreparedStatement(app.dbUnixSocketFile, "CALL NodeOps.getKeyspaces()");
            Row row = result.one();
            List<String> keyspaces = null;
            if (row != null)
            {
                List<String> allKeyspaces = row.getList(0, String.class);
                keyspaces = allKeyspaces.stream()
                        .filter(ks -> ks.equals(keyspaceName) || StringUtils.isBlank(keyspaceName))
                        .collect(Collectors.toList());
            }

            return Response.ok(jsonMapper.writeValueAsString(keyspaces), MediaType.APPLICATION_JSON).build();
        });
    }

    @GET
    @Path("/replication")
    @Produces({MediaType.TEXT_PLAIN, MediaType.APPLICATION_JSON})
    @ApiResponse(responseCode = "200", description = "Keyspace Replication Settings",
        content = @Content(
            mediaType = MediaType.APPLICATION_JSON,
            examples = @ExampleObject(
                value = "{\n    \"class\": \"org.apache.cassandra.locator.SimpleStrategy\",\n    \"replication_factor\": \"2\"\n}"
            )
        )
    )
    @ApiResponse(responseCode = "400", description = "Keyspace name not provided",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "Get keyspace replication failed. Non-empty 'keyspaceName' must be provided"
            )
        )
    )
    @ApiResponse(responseCode = "404", description = "Keyspace name not found",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "Get keyspace replication failed. Keyspace 'my_keyspace' does not exist."
            )
        )
    )
    @Consumes(MediaType.APPLICATION_JSON)
    @Operation(summary = "Get the replication settings of an existing keyspace", operationId = "replication")
    public Response getReplication(@Parameter(required = true) @QueryParam(value="keyspaceName")String keyspaceName) {
        if (StringUtils.isBlank(keyspaceName)) {
            return Response.status(HttpStatus.SC_BAD_REQUEST)
                    .entity("Get keyspace replication failed. Non-empty 'keyspaceName' must be provided").build();
        }
        return NodeOpsResources.handle(() ->
        {
            ResultSet result = cqlService.executePreparedStatement(
                    app.dbUnixSocketFile, "CALL NodeOps.getReplication(?)", keyspaceName);
            Row row = result.one();
            if (row == null) {
                return Response.status(HttpStatus.SC_NOT_FOUND)
                        .entity(String.format("Get keyspace replication failed. Keyspace '%s' does not exist.", keyspaceName)).build();
            } else {
                Map<String, String> replication = row.getMap(0, String.class, String.class);
                assert replication != null;
                return Response.ok(replication, MediaType.APPLICATION_JSON).build();
            }
        });
    }
}

