public class ResponseTools {

    public static String getSingleRowStringResponse(final File dbUnixSocketFile, CqlService cqlService, String query, Object... params) throws ConnectionClosedException {
        Row row = getRow(dbUnixSocketFile, cqlService, query, params);
        String queryResponse = null;
        if (row != null)
        {
            queryResponse = row.getString(0);
        }

        return queryResponse;
    }

    public static Object getSingleRowResponse(final File dbUnixSocketFile, CqlService cqlService, String query, Object... params) throws ConnectionClosedException {
        Row row = getRow(dbUnixSocketFile, cqlService, query, params);
        Object queryResponse = null;
        if (row != null)
        {
            queryResponse = row.getObject(0);
        }

        return queryResponse;
    }

    private static Row getRow(File dbUnixSocketFile, CqlService cqlService, String query, Object[] params) throws ConnectionClosedException {
        ResultSet rs;

        if(params.length > 0) {
            rs = cqlService.executePreparedStatement(dbUnixSocketFile, query, params);
        } else {
            rs = cqlService.executeCql(dbUnixSocketFile, query);
        }

        Row row = rs.one();
        return row;
    }

}

public class CqlService
{
    private static final Logger logger = LoggerFactory.getLogger(CqlService.class);

    public ResultSet executeCql(File dbUnixSocketFile, String query) throws ConnectionClosedException
    {
        CqlSession session = UnixSocketCQLAccess.get(dbUnixSocketFile).orElse(null);

        if (session == null || session.isClosed())
        {
            throw new ConnectionClosedException("Internal connection to Cassandra closed");
        }

        try
        {
            return session.execute(query);
        }
        catch (NoNodeAvailableException e)
        {
            try
            {
                session.close();
            }
            catch (Throwable t)
            {
                // close quietly
            }

            throw e;
        }
    }

    public ResultSet executePreparedStatement(File cassandraUnixSocketFile, String query,  Object... values) throws ConnectionClosedException
    {
        CqlSession session = UnixSocketCQLAccess.get(cassandraUnixSocketFile).orElse(null);

        if (session == null || session.isClosed())
        {
            throw new ConnectionClosedException("Internal connection to Cassandra closed");
        }

        SimpleStatementBuilder ssb = new SimpleStatementBuilder(query);

        for (Object obj : values)
        {
            ssb = ssb.addPositionalValue(obj);
        }

        try
        {
            return session.execute(ssb.build());
        }
        catch (NoNodeAvailableException e)
        {
            try
            {
                session.close();
            }
            catch (Throwable t)
            {
                // close quietly
            }

            throw e;
        }
    }
}

