            }

            cqlService.executePreparedStatement(app.dbUnixSocketFile,
                    "CALL NodeOps.garbageCollect(?, ?, ?, ?)", tombstoneOption, keyspaceRequest.jobs, keyspaceName, tables);

            return Response.ok("OK").build();
        });
