public class K8OperatorResources
{
    private static final Logger logger = LoggerFactory.getLogger(K8OperatorResources.class);
    private static final ObjectMapper jsonMapper = new ObjectMapper();

    private final ManagementApplication app;
    private final CqlService cqlService;

    public K8OperatorResources(ManagementApplication application)
    {
        this.app = application;
        this.cqlService = application.cqlService;
    }

    @GET
    @Path("/probes/liveness")
    @Operation(summary = "Indicates whether this service is running", operationId = "checkLiveness")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Service is running",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "OK"
            )
        )
    )
    public Response checkLiveness()
    {
        return Response.ok("OK").build();
    }

    @GET
    @Path("/probes/readiness")
    @Operation(summary = "Indicates whether the Cassandra service is ready to service requests", operationId = "checkReadiness")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Service is ready to handle requests",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            examples = @ExampleObject(
                value = "OK"
            )
        )
    )
    @ApiResponse(responseCode = "500", description = "Service is not ready to handle requests")
    public Response checkReadiness()
    {
        return handle(() ->
        {
            ResultSet resultSet = cqlService.executeCql(app.dbUnixSocketFile, "SELECT * from system.local");
            Row result = resultSet.one();

            if (result != null)
            {
                return Response.ok("OK").build();
            }
            else
            {
                Response.ResponseBuilder rb = Response.status(Response.Status.INTERNAL_SERVER_ERROR);
                return rb.build();
            }
        });
    }

    @GET
    @Path("/probes/cluster")
    @Operation(summary = "Indicated whether the Cassandra cluster is able to achieve the specified consistency", operationId = "checkClusterConsistency")
    @Produces({MediaType.TEXT_PLAIN, MediaType.APPLICATION_JSON})
    @ApiResponse(responseCode = "200", description = "Cassandra is able to achieve the specified consistency")
    @ApiResponse(responseCode = "500", description = "Cassandra is unable to achieve the specified consistency",
        content = @Content(
            mediaType = MediaType.APPLICATION_JSON,
            schema = @Schema(
                implementation = Map.class
            ),
            examples = @ExampleObject(
                value = "{\n" +
"    \"[-8842966077830801609, -7599446072150209635]\": [\n" +
"        \"2 replicas required, but only 1 nodes in the ring\"\n" +
"    ],\n" +
"    \"[-7599446072150209635, -6632081829071674136]\": [\n" +
"        \"2 replicas required, but only 1 nodes in the ring\"\n" +
"    ]}"
            )
        )
    )
    public Response checkClusterConsistency(@QueryParam(value="consistency_level")String consistencyLevelStr, @QueryParam(value = "rf_per_dc") Integer rfPerDcVal)
    {
        return handle(() ->
        {
            String consistencyLevel = consistencyLevelStr;
            if (consistencyLevel == null)
                consistencyLevel = "LOCAL_QUORUM";

            Integer rfPerDc = rfPerDcVal;
            if (rfPerDc == null)
                rfPerDc = 3;

            ResultSet result = cqlService.executePreparedStatement(app.dbUnixSocketFile,
                    "CALL NodeOps.checkConsistencyLevel(?, ?)", consistencyLevel, rfPerDc);

            Map<List, List> response = result.one().getMap("result", List.class, List.class);

            if (response.isEmpty())
                return Response.ok().build();

            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity(jsonMapper.writeValueAsString(response))
                    .type(MediaType.APPLICATION_JSON)
                    .build();
        });
    }

    @POST
    @Path("/ops/seeds/reload")
    @Operation(summary = "Reload the seed node list from the seed provider", operationId = "seedReload")
    @Produces(MediaType.APPLICATION_JSON)
    @ApiResponse(responseCode = "200", description = "List of new seeds after reload",
        content = @Content(
            mediaType = MediaType.APPLICATION_JSON,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "[127.0.0.1, 127.0.0.2]")
        )
    )
    public Response seedReload()
    {
        return handle(() ->
        {
            ResultSet result = cqlService.executeCql(app.dbUnixSocketFile, "CALL NodeOps.reloadSeeds()");

            List<String> response = result.one().getList("result", String.class);

            return Response.ok(jsonMapper.writeValueAsString(response), MediaType.APPLICATION_JSON).build();
        });
    }

    @GET
    @Path("/ops/executor/job")
    @Operation(summary = "Returns Job details for the supplied Job ID", operationId = "getJobStatus")
    @Produces({MediaType.APPLICATION_JSON, MediaType.TEXT_PLAIN})
    @ApiResponse(responseCode = "200", description = "Map of job details",
        content = @Content(
            mediaType = MediaType.APPLICATION_JSON,
            schema = @Schema(implementation = Job.class)
        )
    )
    @ApiResponse(responseCode = "404", description = "Job not found",
        content = @Content(
            mediaType = MediaType.APPLICATION_JSON,
            schema = @Schema(implementation = Job.class)
        )
    )
    public Response getJobStatus(@Parameter(required = true) @QueryParam(value="job_id") String jobId) {
        return handle(() -> {
            Map<String, String> jobResponse = (Map<String, String>) ResponseTools.getSingleRowResponse(app.dbUnixSocketFile, cqlService, "CALL NodeOps.jobStatus(?)", jobId);
            if(jobResponse.isEmpty()) {
                return Response.status(Response.Status.NOT_FOUND).entity(jobResponse).build();
            }
            return Response.ok(jobResponse, MediaType.APPLICATION_JSON).build();
        });
    }
}

@Path("/api/v0/lifecycle")
public class LifecycleResources
{
    private static final Logger logger = LoggerFactory.getLogger(LifecycleResources.class);
    private final ManagementApplication app;

    static final YAMLMapper yamlMapper = new YAMLMapper();
    static final String PROFILE_PATTERN = "[0-9a-zA-Z\\-_]+";
    static final String IPV4_PATTERN = "^((0|1\\d?\\d?|2[0-4]?\\d?|25[0-5]?|[3-9]\\d?)\\.){3}(0|1\\d?\\d?|2[0-4]?\\d?|25[0-5]?|[3-9]\\d?)$";
    private ObjectMapper objectMapper = new ObjectMapper();

    public LifecycleResources(ManagementApplication app)
    {
        this.app = app;
    }

    /**
     * Starts a Cassandra/DSE node
     *
     * Handles the following:
     *   - Cassandra pid found and can connect: status 202
     *   - Cassandra pid not found and can not connect: status 201
     *   - Cassandra pid not found but can connect: status 206
     *   - Cassandra pid found but can not connect: status 204
     *
     * @return
     */
    @Path("/start")
    @POST
    @Operation(description = "Starts Cassandra/DSE", operationId = "startNode")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "201", description = "Cassandra started successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "OK")
        )
    )
    @ApiResponse(responseCode = "202", description = "Cassandra already running and can connect")
    @ApiResponse(responseCode = "204", description = "Cassandra already running but can't connect")
    @ApiResponse(responseCode = "206", description = "Cassandra process not found but can connect")
    @ApiResponse(responseCode = "420", description = "Cassandra could not start successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "Error starting Cassandra")
        )
    )
    @ApiResponse(responseCode = "500", description = "Error trying to start Cassandra",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "error message")
        )
    )
    public synchronized Response startNode(@QueryParam("profile") String profile, @QueryParam("replace_ip") String replaceIp)
    {
        app.setRequestedState(STARTED);

        //Todo we should add a CALL getPid command and compare;
        boolean canConnect;
        try
        {
            CqlSession session = UnixSocketCQLAccess.get(app.dbUnixSocketFile).get();
            session.execute("SELECT * FROM system.peers");

            canConnect = true;
        }
        catch (Throwable t)
        {
            logger.debug("Could not connect:", t);
            canConnect = false;
        }

        try
        {
            Optional<Integer> maybePid = findPid();

            if (maybePid.isPresent())
            {
                return Response.status(canConnect ? HttpStatus.SC_ACCEPTED : HttpStatus.SC_NO_CONTENT).build();
            }
            else if (canConnect)
                return Response.status(HttpStatus.SC_PARTIAL_CONTENT).build();
        }
        catch (Throwable t)
        {
            logger.error("Error checking pid", t);
            return Response.serverError().entity(Entity.text(t.getLocalizedMessage())).build();
        }

        try
        {
            String extra = System.getenv("JVM_EXTRA_OPTS");
            ImmutableMap.Builder<String, String> envArgsBuilder = ImmutableMap.builder();

            if (extra != null)
                envArgsBuilder.put("JVM_EXTRA_OPTS", extra);

            Map<String, String> environment = envArgsBuilder.build();
            StringBuilder extraArgs = new StringBuilder();

            if (profile != null)
            {
                app.setActiveProfile(profile);

                extraArgs.append("-Dcassandra.config=file:///tmp/").append(profile).append("/cassandra.yaml")
                        .append(" -Dcassandra-rackdc.properties=file:///tmp/").append(profile).append("/node-topology.properties");
            }

            if (replaceIp != null)
            {
                if (!replaceIp.matches(IPV4_PATTERN))
                    return Response.serverError().entity(Entity.text("Invalid replace IP passed: " + replaceIp)).build();

                extraArgs.append("-Dcassandra.replace_address_first_boot=").append(replaceIp);
            }

            String cassandraOrDseCommand = app.dbExe.getAbsolutePath();
            if (cassandraOrDseCommand.endsWith("dse"))
            {
                cassandraOrDseCommand += " cassandra";
            }

            //Delete stale file if it exists
            if (app.dbUnixSocketFile.exists())
                FileUtils.deleteQuietly(app.dbUnixSocketFile);

            // ensure Cassandra will be able to write to the log directory, or the process won't start
            String mgmtApiStartupLogDir = System.getenv("MGMT_API_LOG_DIR");
            if (mgmtApiStartupLogDir == null)
            {
                // use default
                logger.debug("MGMT_API_LOG_DIR is not set, using default of /var/log/cassandra");
                mgmtApiStartupLogDir = "/var/log/cassandra";
            }

            boolean started = false;

            if (!verifyOrCreateLogDirectory(mgmtApiStartupLogDir))
            {
                logger.error(String.format(
                        "Process cannot write to %s. Please ensure that permissions are set correctly and that the MGMT_API_LOG_DIR environment variable is set to the desired log directory.",
                        mgmtApiStartupLogDir));
            }
            else
            {
                started = ShellUtils.executeShellWithHandlers(
                      String.format("nohup %s %s -R -Dcassandra.server_process -Dcassandra.skip_default_role_setup=true -Ddb.unix_socket_file=%s %s %s > %s/stdout.log 2> %s/stderr.log",
                              profile != null ? "/tmp/" + profile + "/env.sh" : "",
                              cassandraOrDseCommand,
                              app.dbUnixSocketFile.getAbsolutePath(),
                              extraArgs.toString(),
                              String.join(" ", app.dbExtraJvmArgs),
                              mgmtApiStartupLogDir,
                              mgmtApiStartupLogDir),
                      (input, err) -> true,
                      (exitCode, err) -> {
                          logger.error("Error starting Cassandra: {}", err.lines().collect(Collectors.joining("\n")));
                          return false;
                      },
                      environment);
            }

            if (started)
                logger.info("Started Cassandra");
            else
                logger.warn("Error starting Cassandra");

            return Response.status(started ? HttpStatus.SC_CREATED : HttpStatus.SC_METHOD_FAILURE)
                    .entity(started ? "OK\n" : "Error starting Cassandra").build();
        }
        catch (Throwable t)
        {
            return Response.serverError().entity(Entity.text(t.getLocalizedMessage())).build();
        }
    }

    @Path("/stop")
    @POST
    @Operation(description = "Stops Cassandra/DSE. Keeps node from restarting automatically until /start is called", operationId = "stopNode")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Cassandra stopped successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "OK")
        )
    )
    @ApiResponse(responseCode = "500", description = "Cassandra not stopped successfully",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "Killing Cassandra Failed")
        )
    )
    public synchronized Response stopNode()
    {
        app.setRequestedState(STOPPED);

        try
        {
            // 30 Seconds
            int tries = 6;
            int sleepSeconds = 5;

            do
            {
                Optional<Integer> maybePid = findPid();

                if (!maybePid.isPresent())
                {
                    logger.info("Cassandra already stopped");
                    return Response.ok("OK\n").build();
                }

                Boolean stopped = ShellUtils.executeShellWithHandlers(
                        String.format("kill %d", maybePid.get()),
                        (input, err) -> true,
                        (exitCode, err) -> false);

                if (!stopped)
                    logger.warn("Killing Cassandra failed");

                Uninterruptibles.sleepUninterruptibly(sleepSeconds, TimeUnit.SECONDS);
            } while (tries-- > 0);


            Optional<Integer> maybePid = findPid();
            if (maybePid.isPresent())
            {
                Boolean stopped = ShellUtils.executeShellWithHandlers(
                        String.format("kill -9 %d", maybePid.get()),
                        (input, err) -> true,
                        (exitCode, err) -> false);

                if (!stopped)
                {
                    logger.info("Cassandra not stopped trying with kill -9");
                    return Response.serverError().entity(Entity.text("Killing Cassandra Failed")).build();
                }

                Uninterruptibles.sleepUninterruptibly(sleepSeconds, TimeUnit.SECONDS);

                maybePid = findPid();
                if (maybePid.isPresent())
                {
                    logger.info("Cassandra is not able to die");
                    return Response.serverError().entity(Entity.text("Killing Cassandra Failed")).build();
                }
            }

            return Response.ok("OK\n").build();
        }
        catch (Throwable t)
        {
            logger.error("Error when calling stop", t);
            return Response.serverError().entity(Entity.text(t.getLocalizedMessage())).build();
        }
    }

    private JsonNode findCassandraYaml() throws IOException
    {
        File cassandraConfig = null;

        if (System.getenv("CASSANDRA_CONF") != null)
        {
            cassandraConfig = new File(System.getenv("CASSANDRA_CONF") + "/cassandra.yaml");
        }
        else
        {
            cassandraConfig = new File(app.dbHome, "conf/cassandra.yaml");
        }

        if (cassandraConfig.exists() && cassandraConfig.isFile())
            return yamlMapper.readTree(cassandraConfig);

        throw new IOException("cassandra.yaml not found");
    }

    @Path("/configure")
    /**
     * Hiding both "configure" endpoints to prevent OpenAPI spec generation from happening. Having 2
     * methods handling the same endpoint and only differing on the @Consumes request MIME type causes
     * the generation to fail to document the endpoint correctly. For now, we will annotate both these
     * methods with @Hidden so that they still exist but are not auto generated in the spec file. They
     * are documented by hand in the openapi-configuration.json file in the resources directory of this
     * project for now, as that file is merged with the auto-generated spec to produce the final spec
     * file.
     */
    @Hidden
    @POST
    @Consumes("application/json")
    @Operation(description = "Configure Cassandra. Will fail if Cassandra is already started", operationId = "configureNodeJson")
    @Produces(MediaType.TEXT_PLAIN)
    public synchronized Response configureNodeJson(@QueryParam("profile") String profile, String config)
    {
        try {
            JsonNode jn = objectMapper.readTree(config);
            String yaml = yamlMapper.writeValueAsString(jn);
            return configureNode(profile, yaml);
        } catch (IOException e) {
            return Response.status(Response.Status.NOT_ACCEPTABLE).entity("Invalid JSON:"+ e.getMessage()).build();
        }
    }

    @Path("/configure")
    // Hiding this. See above.
    @Hidden
    @POST
    @Consumes({"application/yaml", "text/yaml"})
    @Operation(description = "Configure Cassandra/DSE. Will fail if Cassandra/DSE is already started", operationId = "configureNode")
    @Produces(MediaType.TEXT_PLAIN)
    public synchronized Response configureNode(@QueryParam("profile") String profile, String yaml)
    {
        if (app.getRequestedState() == STARTED ) {
            return Response.status(Response.Status.NOT_ACCEPTABLE).entity("Cassandra is running, try /api/v0/lifecycle/stop first\n").build();
        }

        //FIXME: Regex
        if (profile == null)
            return Response.status(Response.Status.BAD_REQUEST.getStatusCode()).entity("The profile query parameter is required, try /api/v0/lifecycle/configure?profile=<profile>\n").build();

        //Find cassandra yaml
        try
        {
            JsonNode jn = yamlMapper.readTree(yaml.getBytes());

            jn = jn.get("spec");
            if (jn == null) {
                return Response.status(Response.Status.BAD_REQUEST).entity("spec missing\n").build();
            }

            JsonNode clusterNameJsonNode = jn.get("clusterName");
            if (clusterNameJsonNode == null){
                return Response.status(Response.Status.BAD_REQUEST).entity("cluster name missing\n").build();
            }
            String clusterName = clusterNameJsonNode.textValue();

            jn = jn.get("config");
            if (jn == null)
                return Response.status(Response.Status.BAD_REQUEST.getStatusCode()).entity("config missing\n").build();

            JsonNode nodeTopology = jn.get("node-topology");
            String dc = "vdc1";
            String rack = "vrack1";
            if (nodeTopology != null)
            {
                if (nodeTopology.has("dc"))
                    dc = nodeTopology.get("dc").asText(dc);

                if (nodeTopology.has("rack"))
                    rack = nodeTopology.get("rack").asText(rack);
            }

            new File("/tmp/" + profile).mkdirs();

            StringBuilder sb = new StringBuilder()
                    .append("dc=").append(dc).append("\n")
                    .append("rack=").append(rack).append("\n");

            FileUtils.write(new File("/tmp/" + profile + "/node-topology.properties"), sb.toString(), false);

            JsonNode defaultCYaml = findCassandraYaml();
            JsonNode cassandraYaml = jn.get("cassandra-yaml");

            ObjectNode customYaml = defaultCYaml.deepCopy();

            Iterator<Map.Entry<String, JsonNode>> it = cassandraYaml.fields();
            while (it.hasNext())
            {
                Map.Entry<String, JsonNode> e = it.next();
                customYaml.set(e.getKey(), e.getValue());
            }

            if (clusterName != null)
                customYaml.set("cluster_name", TextNode.valueOf(clusterName));

            yamlMapper.writeValue(new File("/tmp/" + profile + "/cassandra.yaml"), customYaml);

            String jvmMaxHeap = null;
            String jvmHeapNew = null;
            String jvmExtraOpts = null;
            JsonNode jvmOpts = jn.get("jvm-server-options");
            if (jvmOpts != null)
            {
                if (jvmOpts.has("max_heap_size"))
                    jvmMaxHeap = jvmOpts.get("max_heap_size").asText();

                if (jvmOpts.has("heap_new_size"))
                    jvmHeapNew = jvmOpts.get("heap_new_size").asText();

                if ((jvmMaxHeap == null) != (jvmHeapNew == null))
                    return Response.status(Response.Status.BAD_REQUEST).entity("Both max_heap_size and heap_new_size must be defined").build();

                if (jvmOpts.has("additional-jvm-opts"))
                    jvmExtraOpts = Streams.stream(jvmOpts.withArray("additional-jvm-opts").elements())
                            .map(JsonNode::asText).collect(Collectors.joining(" "));
            }

            sb = new StringBuilder();
            sb.append("#!/bin/sh\n");

            if (jvmMaxHeap != null)
                sb.append("export MAX_HEAP_SIZE=").append(jvmMaxHeap).append("\n")
                  .append("export HEAP_NEWSIZE=").append(jvmHeapNew).append("\n");

            if (jvmExtraOpts != null)
                sb.append("export JVM_EXTRA_OPTS=\"$JVM_EXTRA_OPTS ").append(jvmExtraOpts).append("\"\n");

            sb.append("exec $*\n");

            File envScript = new File("/tmp/" + profile + "/env.sh");
            FileUtils.write(envScript, sb.toString(), false);

            envScript.setExecutable(true);
        }
        catch (IOException e)
        {
            e.printStackTrace();
            return Response.serverError().build();
        }

        return Response.ok().entity("OK\n").build();
    }

    @Path("/pid")
    @GET
    @Operation(description = "The PID of Cassandra/DSE, if it's running", operationId = "getPID")
    @Produces(MediaType.TEXT_PLAIN)
    @ApiResponse(responseCode = "200", description = "Cassandra Process ID",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "OK")
        )
    )
    @ApiResponse(responseCode = "204", description = "No Cassandra Process running")
    @ApiResponse(responseCode = "500", description = "Error finding Cassandra Process",
        content = @Content(
            mediaType = MediaType.TEXT_PLAIN,
            schema = @Schema(implementation = String.class),
            examples = @ExampleObject(value = "error message")
        )
    )
    public Response getPID()
    {
        try
        {
            Optional<Integer> maybePid = findPid();
            if (maybePid.isPresent())
                return Response.ok(Integer.toString(maybePid.get())).build();

            return Response.status(HttpStatus.SC_NO_CONTENT).build();
        }
        catch (Throwable t)
        {
            logger.error("Error when getting pid", t);
            return Response.serverError().entity(t.getLocalizedMessage()).build();
        }
    }

    private Optional<Integer> findPid() throws IOException
    {
        return UnixCmds.findDbProcessWithMatchingArg("-Ddb.unix_socket_file=" + app.dbUnixSocketFile.getAbsolutePath());
    }

    /**
     * Verifies that the provided log directory can be written. Will attempt to create the directory
     * if it does not exist.
     * @param logDir The directory to verify write permissions
     * @return true if the directory can be written to or created, false otherwise.
     */
    private boolean verifyOrCreateLogDirectory(String logDir) {
        File logPath = new File(logDir);
        if (logPath.exists()) {
            return logPath.isDirectory() && logPath.canWrite();
        }
        else
        {
            return logPath.mkdirs();
        }
    }
}

public class CreateOrAlterKeyspaceRequest implements Serializable
{
    @JsonProperty(value = "keyspace_name", required = true)
    public final String keyspaceName;

    @JsonProperty(value = "replication_settings", required = true)
    public final List<ReplicationSetting> replicationSettings;

    @JsonCreator
    public CreateOrAlterKeyspaceRequest(@JsonProperty("keyspace_name") String keyspaceName, @JsonProperty("replication_settings") List<ReplicationSetting> replicationSettings)
    {
        this.keyspaceName = keyspaceName;
        this.replicationSettings = replicationSettings;
    }

    public Map<String, Integer> replicationSettingsAsMap()
    {
        Map<String, Integer> result = new HashMap<>(replicationSettings.size());
        replicationSettings.forEach(r -> result.put(r.dcName, r.replicationFactor));
        return result;
    }
}

public class FeatureSet implements Serializable {

    public enum Feature {
        ASYNC_SSTABLE_TASKS("async_sstable_tasks"),
        FULL_QUERY_LOGGING("full_query_logging"),
        REBUILD("rebuild"),
        ASYNC_UPGRADE_SSTABLE_TASK("async_upgrade_sstable_task"),
        ASYNC_COMPACTION_TASKS("async_compaction_task"),
        ASYNC_SCRUB_TASK("async_scrub_task"),
        ASYNC_MOVE_TASK("async_move_task");

        @JsonValue
        private String featureName;

        Feature(String name) {
            this.featureName = name;
        }
    }


    @JsonProperty(value = "cassandra_version")
    private String cassandraVersion;

    @JsonProperty(value = "mgmt_version")
    private String mgmtVersion;

    @JsonProperty(value = "features")
    private List<Feature> features;

    /**
     * Simplified method to return all Features as the available list
     */
    public FeatureSet(String cassandraVersion, String managementApiVersion) {
        this(cassandraVersion, managementApiVersion, Arrays.asList(Feature.values()));
    }

    @JsonCreator
    public FeatureSet(@JsonProperty(value = "cassandra_version") String cassandraVersion, @JsonProperty(value = "mgmt_version") String managementApiVersion, @JsonProperty(value = "features") List<Feature> availableFeatures) {
        this.cassandraVersion = cassandraVersion;
        this.mgmtVersion = managementApiVersion;
        this.features = availableFeatures;
    }

    public String getCassandraVersion() {
        return cassandraVersion;
    }

    public String getMgmtVersion() {
        return mgmtVersion;
    }

    public List<Feature> getFeatures() {
        return features;
    }
}

public class RepairRequest
{

    @JsonProperty(value = "keyspace_name", required = true)
    public final String keyspaceName;

    @JsonProperty(value = "tables", required = false)
    public final List<String> tables;

    @JsonProperty(value = "full", required = false)
    public final Boolean full;

    @JsonCreator
    public RepairRequest(@JsonProperty("keyspace_name") String keyspaceName, @JsonProperty("tables") List<String> tables, @JsonProperty(value = "full") Boolean full)
    {
        this.keyspaceName = keyspaceName;
        this.tables = tables;
        this.full = full == null ? Boolean.FALSE : full;
    }

  @Override
  public int hashCode() {
    int hash = 7;
    hash = 89 * hash + Objects.hashCode(this.keyspaceName);
    hash = 89 * hash + Objects.hashCode(this.tables);
    hash = 89 * hash + Objects.hashCode(this.full);
    return hash;
  }

  @Override
  public boolean equals(Object obj) {
    if (this == obj)
    {
        return true;
    }
    if (obj == null)
    {
        return false;
    }
    if (getClass() != obj.getClass())
    {
        return false;
    }

    final RepairRequest other = (RepairRequest) obj;
    if (!Objects.equals(this.keyspaceName, other.keyspaceName))
    {
        return false;
    }
    if (!Objects.equals(this.tables, other.tables))
    {
        return false;
    }
    if (!Objects.equals(this.full, other.full))
    {
        return false;
    }
    return true;
  }
}

